package vn.rtr.aeris.native94;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.regex.*;import java.util.zip.*;
/** Bounded immutable snapshot. Integrity only; prefixes are not completed missions. */
public final class DiagnosticArchive91 {
 public static final int MAX=24*1024*1024,TRACE=1024*1024;private static final Pattern LINE=Pattern.compile("\\{\"n\":([0-9]+),\"elapsedMs\":([0-9]+),\"previous\":\"([a-f0-9]*)\",\"payloadBase64\":\"([A-Za-z0-9+/=]+)\",\"sha256\":\"([a-f0-9]{64})\"\\}");
 public static final class Prefix{public final String head;public final int count;Prefix(String h,int n){head=h;count=n;}}
 public static Prefix prefix(byte[] raw)throws IOException{if(raw.length<1||raw.length>TRACE||raw[raw.length-1]!=10)throw new IOException("TRACE_BOUND_OR_TORN");String text=new String(raw,StandardCharsets.US_ASCII),previous="";long last=-1;int n=0;for(String line:text.split("\n")){Matcher m=LINE.matcher(line);if(!m.matches()||++n>512||Long.parseLong(m.group(1))!=n||!m.group(3).equals(previous))throw new IOException("TRACE_ORDER_FORMAT");long t=Long.parseLong(m.group(2));if(t<last)throw new IOException("TRACE_CLOCK");last=t;byte[] p;try{p=Base64.getDecoder().decode(m.group(4));}catch(Exception e){throw new IOException("TRACE_BASE64");}if(p.length<1||p.length>16384)throw new IOException("TRACE_PAYLOAD_BOUND");String body=line.substring(0,line.lastIndexOf(",\"sha256\""))+"}";String h=DraftStore.hash(body.getBytes(StandardCharsets.US_ASCII));if(!h.equals(m.group(5)))throw new IOException("TRACE_SHA");previous=h;}return new Prefix(previous,n);}
 public static byte[] bounded(Path p,int max)throws IOException{if(Files.isSymbolicLink(p)||!Files.isRegularFile(p)||Files.size(p)>max)throw new IOException("SNAPSHOT_PATH_BOUND");return Files.readAllBytes(p);}
 public static String manifest(LinkedHashMap<String,byte[]> files,String context)throws IOException{if(files.size()<2||files.size()>25||!files.containsKey("workspace.zip"))throw new IOException("MEMBER_COUNT");long total=0;StringBuilder rows=new StringBuilder();for(Map.Entry<String,byte[]>e:files.entrySet()){String name=e.getKey();if(!name.equals("workspace.zip")&&!name.matches("diagnostics/[a-f0-9-]{36}\\.jsonl"))throw new IOException("MEMBER_NAME");byte[] b=e.getValue();total+=b.length;if(total>MAX||b.length==0||b.length>(name.equals("workspace.zip")?Workspaces.LIMIT:TRACE))throw new IOException("EXPANDED_BOUND");if(rows.length()>0)rows.append(',');rows.append("{\"name\":").append(Json.quote(name)).append(",\"bytes\":").append(b.length).append(",\"sha256\":").append(Json.quote(DraftStore.hash(b)));if(!name.equals("workspace.zip")){Prefix p=prefix(b);rows.append(",\"extent\":\"COMMITTED_PREFIX\",\"head\":").append(Json.quote(p.head)).append(",\"records\":").append(p.count);}rows.append('}');}if(context==null||context.length()>8192)throw new IOException("CONTEXT_BOUND");return "{\"format\":\"aeris-diagnostic91\",\"version\":1,\"sourceAuthenticated\":false,\"authorityRestorable\":false,\"actualImages\":0,\"context\":"+context+",\"files\":["+rows+"]}";}
 public static byte[] build(LinkedHashMap<String,byte[]> files,String context)throws IOException{byte[] manifest=manifest(files,context).getBytes(StandardCharsets.UTF_8);ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(out)){put(z,"manifest.json",manifest);for(Map.Entry<String,byte[]>e:files.entrySet())put(z,e.getKey(),e.getValue());}byte[] result=out.toByteArray();if(result.length>MAX)throw new IOException("ZIP_BOUND");return result;}
 private static void put(ZipOutputStream z,String name,byte[] b)throws IOException{ZipEntry e=new ZipEntry(name);e.setTime(0);e.setMethod(ZipEntry.STORED);e.setSize(b.length);e.setCompressedSize(b.length);CRC32 crc=new CRC32();crc.update(b);e.setCrc(crc.getValue());z.putNextEntry(e);z.write(b);z.closeEntry();}
 public static void publish(Path p,byte[] b)throws IOException{if(b.length>MAX||Files.exists(p,LinkOption.NOFOLLOW_LINKS))throw new IOException("EXCLUSIVE_ARTIFACT");try(java.nio.channels.FileChannel out=java.nio.channels.FileChannel.open(p,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS)){java.nio.ByteBuffer v=java.nio.ByteBuffer.wrap(b);while(v.hasRemaining())out.write(v);out.force(true);}try(java.nio.channels.FileChannel dir=java.nio.channels.FileChannel.open(p.getParent(),StandardOpenOption.READ)){dir.force(true);}}
}
